import { writeFile } from "node:fs/promises";
import { CUES, createRecipe, renderRecipe } from "uisfx";

// Run after updating uisfx to keep displayed durations in sync, including tails.
// Audio itself is rendered lazily in the browser, never bundled.
const durations = Object.fromEntries(CUES.map(({ name }) => [
  name, renderRecipe(createRecipe("glass", name), 44100).duration,
]));
await writeFile(new URL("../src/glass-durations.ts", import.meta.url),
  "// Generated by scripts/prepare-glass.mjs from uisfx (Glass only).\n" +
  `export const glassDurations = ${JSON.stringify(durations, null, 2)} as const;\n`,
);
